mapper.select:
SELECT E.ChnlCode, E.EventCode, E.EventName, E.EventDesc, E.EventStartDate, E.EventEndDate, E.ImgName, E.ImgLink, E.ImgWidth, E.ImgHeight, E.StoreCode, E.ParentEventCode, E.EventLevel, E.EventSeq, E.AdultYn, E.ColCnt, E.ReviewYn, E.TmplCode, E.BoardYn, E.State, E.Remark, E.RegistDate, E.RegistId, E.RegistName, E.ChangeDate, E.ChangeId, E.ChangeName, (SELECT COUNT(*) FROM shopion.tStrEvent C WHERE C.ChnlCode = E.ChnlCode AND C.ParentEventCode = E.EventCode) AS ChildCount FROM shopion.tStrEvent E
AND E.ChnlCode = #{pChnlCode}
AND E.ParentEventCode = #{pParentEventCode}
AND E.EventLevel = 0
ORDER BY E.EventSeq

SELECT E.ChnlCode, E.EventCode, E.EventName, E.EventDesc, E.EventStartDate, E.EventEndDate, E.ImgName, E.ImgLink, E.ImgWidth, E.ImgHeight, E.StoreCode, E.ParentEventCode, E.EventLevel, E.EventSeq, E.AdultYn, E.ColCnt, E.ReviewYn, E.TmplCode, E.BoardYn, E.State, E.Remark, E.RegistDate, E.RegistId, E.RegistName, E.ChangeDate, E.ChangeId, E.ChangeName FROM shopion.tStrEvent E
AND E.ChnlCode = #{pChnlCode}
AND E.EventLevel = #{pEventLevel}
ORDER BY E.EventLevel, E.EventSeq

SELECT MAX(EventCode)
FROM shopion.tStrEvent


        AND ChnlCode = #{pChnlCode}


        AND ParentEventCode = #{pParentEventCode}

SELECT EventHtml
FROM shopion.tStrEvent
WHERE ChnlCode = #{pChnlCode}
  AND EventCode = #{pEventCode}
